import sys, os
from docx import Document
from docx.table import Table
from docx.text.paragraph import Paragraph

def iter_block(doc):
    body = doc.element.body
    for child in body.iterchildren():
        tag = child.tag.split('}')[1]
        if tag == 'p':
            yield Paragraph(child, doc)
        elif tag == 'tbl':
            yield Table(child, doc)

def dump(path, out):
    doc = Document(path)
    lines = []
    for b in iter_block(doc):
        if isinstance(b, Paragraph):
            t = b.text.strip()
            if not t:
                continue
            st = b.style.name if b.style is not None else ''
            pre = ''
            if st.startswith('Heading'):
                lvl = st.replace('Heading', '').strip() or '1'
                pre = '#' * (int(lvl) if lvl.isdigit() else 1) + ' '
            elif 'List' in st:
                pre = '- '
            lines.append(pre + t)
        else:
            lines.append('[TABLE]')
            for row in b.rows:
                cells = []
                prev = None
                for c in row.cells:
                    if c._tc is prev:
                        continue
                    prev = c._tc
                    cells.append(c.text.strip().replace('\n', ' / '))
                lines.append('| ' + ' | '.join(cells) + ' |')
            lines.append('[/TABLE]')
    with open(out, 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines))

outdir = sys.argv[1]
for p in sys.argv[2:]:
    name = os.path.splitext(os.path.basename(p))[0].replace(' ', '_').replace('’', '')
    dump(p, os.path.join(outdir, name + '.txt'))
    print(name, os.path.getsize(os.path.join(outdir, name + '.txt')))

